/* SPDX-License-Identifier: BSD-3-Clause */
/* ext/ionosphere: IONEX reading and interpolation against an independent implementation of the
 * IONEX description (tests/data/ionosphere, generated by a Python script that wrote the file and
 * its interpolations), and the single-layer pierce point and mapping against the intersection
 * of the ray with the shell computed in Cartesian coordinates. */
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "mtest.h"
#include "myb/cmath.h"
#include "myb_ionosphere.h"

#define DEG (3.14159265358979323846 / 180.0)

static char* read_file(const char* path, size_t* size) {
  FILE* f = fopen(path, "rb");
  if (f == NULL) {
    return NULL;
  }
  char* buf = malloc(1 << 20);
  *size = buf != NULL ? fread(buf, 1, (1 << 20) - 1, f) : 0;
  fclose(f);
  return buf;
}

static void test_ionex(void) {
  size_t size = 0;
  char* text = read_file(MYB_TEST_DATA_DIR "/ionosphere/synthetic.inx", &size);
  MT_CHECK(text != NULL);
  if (text == NULL) {
    return;
  }
  myb_ionex* maps = NULL;
  myb_diag diag;
  MT_CHECK(myb_ionex_load(text, size, NULL, &maps, &diag) == MYB_OK);
  if (maps == NULL) {
    printf("%ld: %s\n", diag.line, diag.message);
    free(text);
    return;
  }
  double radius = 0.0;
  double height = 0.0;
  myb_ionex_shell(maps, &radius, &height);
  MT_CHECK(radius == 6371000.0 && height == 450000.0);
  FILE* f = fopen(MYB_TEST_DATA_DIR "/ionosphere/expected.txt", "r");
  MT_CHECK(f != NULL);
  int rows = 0;
  int ranges = 0;
  double worst = 0.0;
  char line[256];
  for (int guard = 0; f != NULL && guard < 1000 && fgets(line, sizeof line, f) != NULL; ++guard) {
    if (line[0] == '#') {
      continue;
    }
    double mjd = 0.0;
    double lat = 0.0;
    double lon = 0.0;
    char rest[64];
    if (sscanf(line, "%lf %lf %lf %63s", &mjd, &lat, &lon, rest) != 4) {
      MT_CHECK(0);
      break;
    }
    double v = 0.0;
    const myb_status st = myb_ionex_vtec(maps, mjd, lat * DEG, lon * DEG, &v);
    if (strcmp(rest, "range") == 0) {
      MT_CHECK(st == MYB_E_RANGE);
      ++ranges;
    } else {
      MT_CHECK(st == MYB_OK);
      const double expected = strtod(rest, NULL);
      worst = fmax(worst, fabs(v - expected) / expected);
    }
    ++rows;
  }
  if (f != NULL) {
    fclose(f);
  }
  printf("IONEX interpolation vs the reference (%d points, %d at a missing value): %.1e\n", rows,
         ranges, worst);
  MT_CHECK(rows == 60 && ranges == 1);
  /* the time is a double MJD: its resolution 7e-12 day (0.6 microsecond) rotates the maps by
   * 2.6e-9 degree, 2e-11 of the values of this steep synthetic field */
  MT_CHECK(worst < 1e-10);
  /* a node at the epoch of map 3 (4 h): latitude 0, longitude 30 -> grid value / 10 TECU */
  double v = 0.0;
  MT_CHECK(myb_ionex_vtec(maps, 60310.0 + 4.0 / 24.0, 0.0, 30.0 * DEG, &v) == MYB_OK);
  const double node = floor(200.0 + 150.0 * myb_cos((30.0 + 60.0 - 30.0) * DEG) + 12.0 + 0.5);
  MT_CHECK(fabs(v - node / 10.0 * 1e16) <= 1e-15 * v);
  /* outside the maps */
  MT_CHECK(myb_ionex_vtec(maps, 60310.0 + 4.1 / 24.0, 0.0, 0.0, &v) == MYB_E_RANGE);
  MT_CHECK(myb_ionex_vtec(maps, 60310.0 + 1.0 / 24.0, 85.0 * DEG, 0.0, &v) == MYB_E_RANGE);
  myb_ionex_destroy(maps);
  /* a header without the grid */
  const char* bad = "     3                                                      # OF MAPS IN FILE\n"
                    "                                                            END OF HEADER\n";
  MT_CHECK(myb_ionex_load(bad, strlen(bad), NULL, &maps, &diag) == MYB_E_FORMAT);
  MT_CHECK(maps == NULL && diag.line == 2);
  free(text);
}

static void test_pierce_point(void) {
  const double r = 6371000.0;
  const double h = 450000.0;
  const double lats[3] = {0.7, -0.3, 1.2};
  const double lons[3] = {0.2, -2.5, 3.0};
  const double azs[3] = {0.4, 2.8, -1.9};
  const double els[3] = {0.5, 0.15, 1.3};
  double worst = 0.0;
  for (int k = 0; k < 3; ++k) {
    double plat = 0.0;
    double plon = 0.0;
    double m = 0.0;
    MT_CHECK(myb_iono_pierce_point(lats[k], lons[k], azs[k], els[k], r, h, 1.0, &plat, &plon,
                                   &m) == MYB_OK);
    /* the ray in Cartesian coordinates: station on the sphere, direction from east-north-up */
    const double sl = myb_sin(lats[k]);
    const double cl = myb_cos(lats[k]);
    const double so = myb_sin(lons[k]);
    const double co = myb_cos(lons[k]);
    const double up[3] = {cl * co, cl * so, sl};
    const double east[3] = {-so, co, 0.0};
    const double north[3] = {-sl * co, -sl * so, cl};
    const double ce = myb_cos(els[k]);
    double d[3];
    for (int i = 0; i < 3; ++i) {
      d[i] = ce * myb_sin(azs[k]) * east[i] + ce * myb_cos(azs[k]) * north[i] +
             myb_sin(els[k]) * up[i];
    }
    /* |r up + s d| = r + h */
    const double b = r * (up[0] * d[0] + up[1] * d[1] + up[2] * d[2]);
    const double s = -b + sqrt(b * b - (r * r - (r + h) * (r + h)));
    double p[3];
    for (int i = 0; i < 3; ++i) {
      p[i] = r * up[i] + s * d[i];
    }
    const double pr = sqrt(p[0] * p[0] + p[1] * p[1] + p[2] * p[2]);
    const double glat = myb_asin(p[2] / pr);
    const double glon = myb_atan2(p[1], p[0]);
    double dl = plon - glon;
    dl -= 6.283185307179586 * floor(dl / 6.283185307179586 + 0.5);
    const double cosz = (p[0] * d[0] + p[1] * d[1] + p[2] * d[2]) / pr;
    worst = fmax(worst, fmax(fabs(plat - glat), fmax(fabs(dl), fabs(m - 1.0 / cosz))));
  }
  printf("pierce points vs the ray-shell intersection: %.1e\n", worst);
  MT_CHECK(worst < 1e-13);
  /* the modified model (alpha < 1) maps less; at the zenith both are 1 */
  double plat = 0.0;
  double plon = 0.0;
  double m1 = 0.0;
  double m2 = 0.0;
  MT_CHECK(myb_iono_pierce_point(0.5, 0.1, 1.0, 0.2, r, 506700.0, 1.0, &plat, &plon, &m1) ==
           MYB_OK);
  MT_CHECK(myb_iono_pierce_point(0.5, 0.1, 1.0, 0.2, r, 506700.0, 0.9782, &plat, &plon, &m2) ==
           MYB_OK);
  MT_CHECK(m2 < m1);
  MT_CHECK(myb_iono_pierce_point(0.5, 0.1, 1.0, 1.5707963267948966, r, h, 0.9782, &plat, &plon,
                                 &m2) == MYB_OK);
  MT_CHECK(fabs(m2 - 1.0) < 1e-15 && fabs(plat - 0.5) < 1e-15);
  MT_CHECK(myb_iono_pierce_point(0.5, 0.1, 1.0, -0.1, r, h, 1.0, &plat, &plon, &m2) ==
           MYB_E_DOMAIN);
}

int main(void) {
  setvbuf(stdout, NULL, _IONBF, 0);
  test_ionex();
  test_pierce_point();
  return mt_finish("test_ionosphere");
}
